-- =====================================================-- Sales Performance Analysis of Walmart Stores-- Advanced SQL Project-- =====================================================-- Task 1: Identifying the Top Branch by Sales Growth RateWITH monthly_sales AS (SELECTBranch AS branch,strftime('%Y-%m', Date) AS month,SUM(Total) AS total_salesFROM walmart_salesGROUP BY Branch, month),sales_growth AS (SELECTbranch,month,total_sales,LAG(total_sales) OVER (PARTITION BY branchORDER BY month) AS previous_month_salesFROM monthly_sales)SELECTbranch,ROUND(AVG(CASEWHEN previous_month_sales IS NOT NULLAND previous_month_sales <> 0THEN ((total_sales - previous_month_sales) / previous_month_sales) * 100END),2) AS avg_growth_rateFROM sales_growthGROUP BY branchORDER BY avg_growth_rate DESC;-- Task 2: Finding the Most Profitable Product Line for Each BranchWITH product_profit AS (SELECTBranch AS branch,"Product line" AS product_line,SUM("Gross income" - cogs) AS profitFROM walmart_salesGROUP BY Branch, "Product line"),ranked_profit AS (SELECTbranch,product_line,ROUND(profit, 2) AS profit,ROW_NUMBER() OVER (PARTITION BY branchORDER BY profit DESC) AS rnFROM product_profit)SELECTbranch,product_line,profitFROM ranked_profitWHERE rn = 1ORDER BY branch;-- Task 3: Analyzing Customer Segmentation Based on SpendingWITH customer_spending AS (SELECT"Customer type" AS customer_type,ROUND(AVG(Total), 2) AS avg_spendingFROM walmart_salesGROUP BY "Customer type")SELECTcustomer_type,avg_spending,CASEWHEN avg_spending >= 350 THEN 'High'WHEN avg_spending >= 200 THEN 'Medium'ELSE 'Low'END AS spending_tierFROM customer_spendingORDER BY avg_spending DESC;-- Task 4: Detecting Anomalies in Sales TransactionsWITH product_avg AS (SELECT"Product line" AS product_line,AVG(Total) AS avg_totalFROM walmart_salesGROUP BY "Product line")SELECTw."Invoice ID" AS invoice_id,w."Product line" AS product_line,ROUND(w.Total, 2) AS transaction_total,ROUND(p.avg_total, 2) AS average_product_total,CASEWHEN w.Total > p.avg_total * 1.5 THEN 'High Anomaly'WHEN w.Total < p.avg_total * 0.5 THEN 'Low Anomaly'ELSE 'Normal'END AS anomaly_statusFROM walmart_sales wJOIN product_avg pON w."Product line" = p.product_lineWHERE w.Total > p.avg_total * 1.5OR w.Total < p.avg_total * 0.5ORDER BY transaction_total DESC;-- Task 5: Most Popular Payment Method by CityWITH payment_counts AS (SELECTCity AS city,Payment AS payment_method,COUNT(*) AS usage_countFROM walmart_salesGROUP BY City, Payment),ranked_payments AS (SELECTcity,payment_method,usage_count,ROW_NUMBER() OVER (PARTITION BY cityORDER BY usage_count DESC) AS rnFROM payment_counts)SELECTcity,payment_method,usage_countFROM ranked_paymentsWHERE rn = 1ORDER BY city;-- Task 6: Monthly Sales Distribution by GenderSELECTstrftime('%Y-%m', Date) AS month,Gender AS gender,ROUND(SUM(Total), 2) AS total_salesFROM walmart_salesGROUP BY month, GenderORDER BY month, Gender;-- Task 7: Best Product Line by Customer TypeWITH sales_by_type AS (SELECT"Customer type" AS customer_type,"Product line" AS product_line,SUM(Total) AS total_salesFROM walmart_salesGROUP BY "Customer type", "Product line"),ranked AS (SELECTcustomer_type,product_line,ROUND(total_sales, 2) AS total_sales,ROW_NUMBER() OVER (PARTITION BY customer_typeORDER BY total_sales DESC) AS rnFROM sales_by_type)SELECTcustomer_type,product_line,total_salesFROM rankedWHERE rn = 1ORDER BY customer_type;-- Task 8: Identifying Repeat CustomersWITH purchases AS (SELECT"Customer type" AS customer_type,Date,LAG(Date) OVER (PARTITION BY "Customer type"ORDER BY Date) AS prev_dateFROM walmart_sales)SELECTcustomer_type,COUNT(*) AS repeat_purchasesFROM purchasesWHERE prev_date IS NOT NULLAND julianday(Date) - julianday(prev_date) <= 30GROUP BY customer_typeORDER BY repeat_purchases DESC;-- Task 9: Finding Top 5 Customers by Sales VolumeSELECT"Customer type" AS customer_type,ROUND(SUM(Total), 2) AS total_salesFROM walmart_salesGROUP BY "Customer type"ORDER BY total_sales DESCLIMIT 5;-- Task 10: Analyzing Sales Trends by Day of the WeekSELECTCASE strftime('%w', Date)WHEN '0' THEN 'Sunday'WHEN '1' THEN 'Monday'WHEN '2' THEN 'Tuesday'WHEN '3' THEN 'Wednesday'WHEN '4' THEN 'Thursday'WHEN '5' THEN 'Friday'WHEN '6' THEN 'Saturday'END AS day_of_week,ROUND(SUM(Total), 2) AS total_salesFROM walmart_salesGROUP BY strftime('%w', Date)ORDER BY total_sales DESC;